from pg import *
from refs import REFS
old={i['id']:i for i in load(11)['items']}
Z=r'(\boldsymbol{x}_0^j,\boldsymbol{u}^j,\boldsymbol{\theta}^j,\boldsymbol{w}^j)'
THM2=r'''**Theorem 2 (Convergence of Random Convex Hulls using (randUP)).** Let $\{'''+Z+r'''\}_{j=1}^m$ be i.i.d. sampled parameters in $\mathcal{X}_0\times\mathcal{U}^{k-1}\times\Theta\times\mathbb{W}^{k-1}$. Define $\boldsymbol{x}_k^j$ according to (1), and denote the resulting convex hulls as $\mathcal{X}_k^m = \mathrm{Co}(\{\boldsymbol{x}_k^j\}_{j=1}^m)$. Assume that the sampling distribution of the parameters satisfies $\mathbb{P}(\boldsymbol{x}_k^j \in G_k) > 0$ for any open set $G_k$ s.t. $\mathcal{X}_k \cap G_k \neq \emptyset$.

Then, as $m\rightarrow\infty$, $\mathcal{X}_k^m$ converges to the convex hull of the reachable set $\mathrm{Co}(\mathcal{X}_k)$ almost surely.'''
items=[]
for n in range(46,51):
    i=f'p0011-b{n-46:03d}'
    items.append(T(i,old[i]['bbox'],REFS[n]))
items+=[
H('p0011-b005',[108,232,229,241],'## A Proof of Theorem 2'),
T('p0011-b006',[108,256,389,266],'For ease of reading, we first restate Theorem 2:'),
T('p0011-b007',[108,268,505,335],THM2),
T('p0011-b009',[108,347,505,390],r'''**Proof.** Without loss of generality, we prove this theorem for any arbitrary fixed time index $k$. For conciseness, we drop the index $k$ and denote $(\boldsymbol{x}^j,\mathcal{X}^m,\mathcal{X}) = (\boldsymbol{x}^j_k,\mathcal{X}^m_k,\mathrm{Co}(\mathcal{X}_k))$, the sampled parameters tuple $\boldsymbol{z}=(\boldsymbol{x}_0,\boldsymbol{u},\boldsymbol{\theta},\boldsymbol{w})\in\mathbb{R}^z$, and the compact parameters set $\mathcal{Z}=\mathcal{X}_0\times\mathcal{U}^{k}\times\Theta\times\mathbb{W}^{k-1}$. Also, let $\boldsymbol{f}(\boldsymbol{z})=\boldsymbol{f}(\boldsymbol{\cdot},\boldsymbol{u}_{k-1},\boldsymbol{\theta},\boldsymbol{w}_{k-1})\circ\ldots\circ\boldsymbol{f}(\boldsymbol{x}_0,\boldsymbol{u}_0,\boldsymbol{\theta},\boldsymbol{w}_{0})$, which is also continuous in $\boldsymbol{z}$.'''),
T('p0011-b010',[108,395,504,428],r'''Let $(\Omega,\mathcal{A}, \mathbb{P})$ a probability space, and $\mathcal{F}$ the family of closed sets in $\mathbb{R}^n$. Define $\mathcal{X}^m:\Omega\rightarrow\mathcal{F}$, with $\mathcal{X}^m(\omega) = \mathrm{Co}(\{\boldsymbol{x}^j\}_{j=1}^m)$. Then, $\{\mathcal{X}^m(\omega), m\geq 1\}$ is a sequence of compact random sets satisfying $\mathcal{X}^1(\omega)\subseteq \mathcal{X}^2(\omega) \subseteq \dots$ almost surely (a.s.).'''),
T('p0011-b011',[107,433,505,488],r'''Indeed, for all $j=1,\dots,m$, $\{\boldsymbol{x}^j\}$ is a random closed set [2]. Then, applying [2, Theorem 1.3.25, (i), (iv)], we obtain that $\mathcal{X}^m=\mathrm{Co}(\{\boldsymbol{x}^j\}_{j=1}^m)$ is a random closed set. Hence $\{\mathcal{X}^m(\omega), m\geq 1\}$ is a sequence of random closed sets satisfying Def. 1. Further, each $\mathcal{X}^m(\omega)$ is compact since it is the convex hull of bounded $\boldsymbol{x}^j$'s, since $\boldsymbol{f}(\cdot)$ is continuous and $\mathcal{Z}$ is compact. Finally, by definition, $\mathcal{X}^m \subseteq\mathcal{X}^{m+1}$ a.s. for all $m$, hence $\mathcal{X}^1(\omega)\subseteq \mathcal{X}^2(\omega) \subseteq \dots$ a.s.'''),
T('p0011-b012',[107,494,505,516],r'''Now that we proved that our convex hulls are random sets, we proceed with the proof that the sequence $\{\mathcal{X}^m(\omega), m\geq 1\}$ converges to $\mathcal{X}$ by proving that we satisfy (**C1**) and (**C2**) of Theorem 1.'''),
T('p0011-b013',[107,520,505,554],r'''(**C1**): Let $K\in \mathcal{K}$ satisfy $\mathcal{X}\cap K = \emptyset$. Since $\boldsymbol{x}^j(\omega)\in\mathcal{X}$ almost surely for all $j$, $\mathcal{X}^m\subset\mathrm{Co}(\mathcal{X})$ almost surely for all $m$. This implies that $\mathcal{X}^m\cap K=\emptyset$ almost surely for all $m$. Thus, $\mathbb{P}(\mathcal{X}^m\cap K\neq\emptyset)=0$ and $\sum_{m=1}^\infty \mathbb{P}(\mathcal{X}^m\cap K\neq\emptyset)=0$. By the first Borel-Cantelli lemma, $\mathbb{P}(\mathcal{X}^m\cap K \neq \emptyset \ \ i.o.) = 0$.'''),
T('p0011-b014',[107,559,505,603],r'''(**C2**): Let $G\in \mathcal{G}$ satisfy $\mathcal{X}\cap G \neq \emptyset$. To prove that $\mathbb{P}(\mathcal{X}^m\cap G = \emptyset \ \ i.o.) = 0$, we proceed in three steps: (1) we show that sampling points $\boldsymbol{x}^j$ within $G$ occurs infinitely often (i.o.); (2) we use the growth property $\mathcal{X}^m\subseteq\mathcal{X}^{m+1}$ to rewrite (**C2**); (3) we relate the probability of sampling $\boldsymbol{x}^j$ within $G$ with the probability of $\mathcal{X}^m$ to intersect with $G$.'''),
T('p0011-b015',[107,608,287,619],r'''(1) The goal is to show $\mathbb{P} (\boldsymbol{x}^j\in G \ \ i.o.) = 1$.'''),
T('p0011-b016',[107,624,505,647],r'''We first note that $\{\omega \,|\, \boldsymbol{x}^j\in G\} = \{\omega \,|\, \boldsymbol{z}^j \ \text{s.t.} \ \boldsymbol{f}(\boldsymbol{z}^j) \in G\}$. Since the parameters $\boldsymbol{z}^j$ are sampled independently for each $j$, it can be shown that $\{\omega\,|\,\boldsymbol{x}^j\in G\}$ are also independent for $j=1,\ldots,m$.'''),
T('p0011-b017',[107,652,504,698],r'''Then, let $\mathcal{Z}_G\subset\mathbb{R}^z$ such that for all $\boldsymbol{z}\in\mathcal{Z}_G$, we have $\boldsymbol{f}(\boldsymbol{z})\in G$. By continuity of $\boldsymbol{f}(\cdot)$, $\mathcal{Z}_G$ is also an open set. Then, since $\mathcal{X}\cap G \neq \emptyset$ and by assumption on the sampling distribution over parameters, we have $\mathbb{P}(\boldsymbol{x}^j\in G) = \mathbb{P}(\boldsymbol{z}^j\in\mathcal{Z}_G)=\alpha_G >0$, where $\alpha_G$ does not depend on $j$ since the parameters $(\boldsymbol{x}_0,\boldsymbol{u},\boldsymbol{\theta},\boldsymbol{w})$ are sampled i.i.d.. Therefore, we obtain $\sum_{j=1}^\infty\mathbb{P}(\boldsymbol{x}^j\in G)=\infty$.'''),
T('p0011-b018',[107,700,504,724],r'''Next, since the events $\{\omega\,|\,\boldsymbol{x}^j\in G\}$ are independent, and by the above, we apply the second Borel-Cantelli lemma to obtain $\mathbb{P} (\boldsymbol{x}^j\in G \ \ i.o.) = \mathbb{P}\big(\cup_{n=1}^\infty\cap_{m=n}^\infty \boldsymbol{x}^j\in G\big) = 1$.'''),
O('p0011-b019',[296,740,316,753],'Page number "11" in the footer.'),
]
save(11, items, 'Compared with a 130 dpi render, two 240 dpi zooms covering Appendix A from its heading to the foot of the page, and the TeX source and .bbl. References [46]-[50] read against the page; the URL of [47] is rejoined (printed over a line break). Appendix heading written "## A Proof of Theorem 2". The restated Theorem 2 is one item with the bold label and printed title; its statement is identical to the main-text Theorem 2 (same TeX), checked again on the zoom (theorem body italics not reproduced). "Proof." (printed in italics) is written as a bold label. All proof paragraphs are rebuilt from TeX with macros expanded and checked symbol by symbol on the zooms: $\\mathbb{R}^z$, $\\mathcal{Z}=\\mathcal{X}_0\\times\\mathcal{U}^{k}\\times\\Theta\\times\\mathbb{W}^{k-1}$ (exponent $k$ on $\\mathcal{U}$ here, $k-1$ in the theorem statement - as printed), $\\mathcal{X}^m\\subset\\mathrm{Co}(\\mathcal{X})$ in (C1), $\\alpha_G>0$, the sums over $m$ and $j$, and the inline union/intersection in the last line. In the definition of $\\boldsymbol{f}(\\boldsymbol{z})$ the composition is printed with baseline dots (\\ldots), unlike equation (2) and the text after (5), which print centred dots. "i.o." is printed in math italics inside the probabilities and kept as such. Printed oddity kept: "i.i.d.. Therefore" (double period). Restored the hyphen in "Borel-Cantelli" dropped by the extractor at a line wrap. The page ends with a complete sentence; no cross-page join.')
